void traverse_bridge_get_twp_line(uint8_t* road_continue)
{
    uint8_t i_start = NEAR_LINE;
    uint8_t i_start2 = 0;
    uint8_t i_start3 = 0;
    uint8_t i_end = FAR_LINE;
    uint8_t mmmm = 0;
    //记录连贯区域编号
    for (uint8_t i = i_start; i > i_end; i--)
    {
        //如果相连编号大于该行白条数，非正常，从此之后都MISS
        if (road_continue[i] > my_road[i].white_num)
        {
            road_continue[i - 1] = MISS;
            i_start2 = i;
            traverse_near_road = i;
            break;
        }
        else
        {
            road_continue[i - 1] = find_continue(i, road_continue[i]);
        }
    }
    for (uint8_t i = i_start2; i > i_end; i--)
    {
        for (uint8_t j = 1; j <= my_road[i].white_num; j++)
        {
            if (my_road[i].connected[j].left < CAMERA_W / 2 && my_road[i].connected[j].right > CAMERA_W / 2)
            {
                i_start3 = i;
                road_continue[i] = j;
                traverse_top_road = i;
                mmmm = 1;
                break;
            }
        }
        if (mmmm == 1)
        {
            break;
        }
    }
    for (uint8_t i = i_start3; i > i_end; i--)
    {
        //如果相连编号大于该行白条数，非正常，从此之后都MISS
        if (road_continue[i] > my_road[i].white_num)
        {
            road_continue[i - 1] = MISS;
        }
        else
        {
            road_continue[i - 1] = find_continue(i, road_continue[i]);
        }
    }
}
void single_side_bridge_two_line(uint8_t* road_continue)
{
    uint8_t white_length;//记录白色的长度
    uint8_t white_length_m = 0;;
    uint8_t mid_x;//白条子中点x坐标
    uint8_t mid_y;//白条子中点y坐标
    uint8_t j_con;
    for (uint8_t i = NEAR_LINE - 1; i > FAR_LINE; i--)
    {
        white_length_m = 0;
        mid_x = 0;
        mid_y = 0;
        j_con = MISS;
        if (road_continue[i + 1] > my_road[i + 1].white_num)
        {
            road_continue[i] = MISS;
        }
        else
        {
            for (uint8_t j = 1; j <= my_road[i].white_num; j++)
            {
                white_length = 0;
                if ((my_road[i].connected[j].left <= my_road[i + 1].connected[road_continue[i + 1]].right) &&
                    (my_road[i].connected[j].right >= my_road[i + 1].connected[road_continue[i + 1]].left))
                {
                    if (my_road[i].white_num == 1)
                    {
                        j_con = j;
                        break;
                    }
                    mid_x = (my_road[i].connected[j].left + my_road[i].connected[j].right) / 2;
                    mid_y = i;
                    for (uint8_t k = mid_y; k > FAR_LINE; k--)
                    {
                        if (IMG[k][mid_x] == white)
                        {
                            white_length++;
                        }
                        if (IMG[k][mid_x] == black)
                        {
                            break;
                        }
                    }
                    if (white_length >= white_length_m)
                    {
                        j_con = j;
                        white_length_m = white_length;
                    }
                }
            }
            road_continue[i] = j_con;
        }
    }
}
//横断桥二次选道
void traverse_bridge_road_choose()
{
    top_road = NEAR_LINE;//赛道最高处所在行数，先初始化话为最低处
    all_range* twhite_range = NULL;
    road* tmy_road = NULL;
    uint8_t istart = NEAR_LINE;
    uint8_t iend = FAR_LINE;
    uint8_t istart2 = 0;
    uint8_t istart3 = 0;
    uint8_t mmmm = 0;
    int while_range_num = 0, roud_while_range_num = 0;
    int road_f = -1;//赛道所在连通域父节点编号，先初始化为-1，以判断是否找到赛道
    //首先先找到该路道截止到第几行
    for (int i = 1; i <= white_range[istart].num; i++)
    {
        if (traverse_mode == 3 || traverse_mode == 4)
        {
            if (white_range[istart].area[i].left <= CAMERA_W / 2 + 40
                && white_range[istart].area[i].right >= CAMERA_W / 2 - 40 && (white_range[istart].area[i].right - white_range[istart].area[i].left) >= 40)
            {
                road_f = find_f(white_range[istart].area[i].connect_num);
            }
        }
        if (traverse_mode == 1)
        {
            if (white_range[istart].area[i].left >= CAMERA_W / 2
                && (white_range[istart].area[i].right - white_range[istart].area[i].left) >= 10)
                road_f = find_f(white_range[istart].area[i].connect_num);
        }
        if (traverse_mode == 2)
        {
            if (white_range[istart].area[i].right <= CAMERA_W / 2
                && (white_range[istart].area[i].right - white_range[istart].area[i].left) >= 10)
                road_f = find_f(white_range[istart].area[i].connect_num);
        }
    }




    for (uint8_t i = istart; i >= iend; i--)
    {
        //变量保存，避免之后写的冗杂且低效
        uint8_t nnnn = 0;
        twhite_range = &white_range[i];
        tmy_road = &my_road[i];
        while_range_num = twhite_range->num;//每行白条数量
        tmy_road->white_num = 0;
        roud_while_range_num = 0;
        if (white_range[i].num == 0)
        {
            istart2 = i;
            mmmm = 1;
            break;
        }
        for (uint8_t j = 1; j <= while_range_num; j++)
        {
            if (find_f(twhite_range->area[j].connect_num) == road_f)
            {
                tmy_road->white_num++; roud_while_range_num++;
                tmy_road->connected[roud_while_range_num].left = twhite_range->area[j].left;
                tmy_road->connected[roud_while_range_num].right = twhite_range->area[j].right;
                tmy_road->connected[roud_while_range_num].width = twhite_range->area[j].right - twhite_range->area[j].left;
                nnnn++;
            }
            else if (j == while_range_num && nnnn == 0)
            {
                istart2 = i;
                mmmm = 1;
                break;
            }
        }
        if (mmmm == 1)
        {
            break;
        }
    }
    for (uint8_t i = istart2; i > iend; i--)
    {
        //变量保存，避免之后写的冗杂且低效
        twhite_range = &white_range[i];
        tmy_road = &my_road[i];
        while_range_num = twhite_range->num;//每行白条数量
        tmy_road->white_num = 0;
        roud_while_range_num = 0;
        for (uint8_t j = 1; j <= white_range[i].num; j++)
        {
            if (white_range[i].area[j].left < CAMERA_W / 2 &&
                white_range[i].area[j].right > CAMERA_W / 2 && (white_range[i].area[j].right - white_range[i].area[j].left) > 25)
            {
                istart3 = i;
                mmmm = 2;
                road_f = find_f(white_range[i].area[j].connect_num);
                break;
            }
        }
        if (mmmm == 2)
        {
            break;
        }
    }
    for (int i = istart3; i > iend; i--)
    {
        //变量保存，避免之后写的冗杂且低效
        twhite_range = &white_range[i];
        tmy_road = &my_road[i];
        while_range_num = twhite_range->num;//每行白条数量
        tmy_road->white_num = 0;
        roud_while_range_num = 0;
        for (int j = 1; j <= while_range_num; j++)
        {
            if (find_f(twhite_range->area[j].connect_num) == road_f)
            {
                tmy_road->white_num++; roud_while_range_num++;
                tmy_road->connected[roud_while_range_num].left = twhite_range->area[j].left;
                tmy_road->connected[roud_while_range_num].right = twhite_range->area[j].right;
                tmy_road->connected[roud_while_range_num].width = twhite_range->area[j].right - twhite_range->area[j].left;
            }
        }
    }
}
void single_side_road_choose(void)
{
    uint8_t istart = NEAR_LINE;
    uint8_t iend = FAR_LINE;
    //top_road = NEAR_LINE;//赛道最高处所在行数，先初始化话为最低处
    int road_f = -1;//赛道所在连通域父节点编号，先初始化为-1，以判断是否找到赛道
    int while_range_num = 0, roud_while_range_num = 0;
    all_range* twhite_range = NULL;
    road* tmy_road = NULL;
    uint8_t mid_x = 0, mid_y = 0;
    uint8_t white_length_m = 0, white_length = 0;
    uint8_t choose_i = 0;
    //寻找赛道所在连通域
    // 寻找最中心的白条子
    for (int i = 1; i <= white_range[istart].num; i++)
    {
        if (white_range[istart].area[i].right - white_range[istart].area[i].left > 30)
        {
            mid_x = (white_range[istart].area[i].left + white_range[istart].area[i].right) / 2;
            white_length = 0;
            for (uint8_t j = istart; j > FAR_LINE; j--)
            {
                if (IMG[j][mid_x] == white)
                {
                    white_length++;
                }
                else if (IMG[j][mid_x] == black)
                {
                    break;
                }
            }
            if (white_length > white_length_m)
            {
                choose_i = i;
                white_length_m = white_length;
            }
        }
    }
    road_f = find_f(white_range[istart].area[choose_i].connect_num);
    //现在我们已经得到了赛道所在连通域父节点编号，接下来把所有父节点编号是road_f的所有白条子扔进赛道数组就行了
    for (int i = istart; i >= iend; i--)
    {
        //变量保存，避免之后写的冗杂且低效
        twhite_range = &white_range[i];
        tmy_road = &my_road[i];
        while_range_num = twhite_range->num;//每行白条数量
        tmy_road->white_num = 0;
        roud_while_range_num = 0;
        for (int j = 1; j <= while_range_num; j++)
        {
            if (find_f(twhite_range->area[j].connect_num) == road_f)
            {
                tmy_road->white_num++; roud_while_range_num++;
                tmy_road->connected[roud_while_range_num].left = twhite_range->area[j].left;
                tmy_road->connected[roud_while_range_num].right = twhite_range->area[j].right;
                tmy_road->connected[roud_while_range_num].width = twhite_range->area[j].right - twhite_range->area[j].left;
            }
        }
    }
}
void get_white_threshold_avg(void)
{
    uint32_t threshold_sum = 0;
    uint8_t threshold_avg = 0;
    uint8_t* map = fullBuffer;
    for (uint8_t i = 20; i < 100; i++)
    {
        for (uint8_t j = 20; j < 168; j++)
        {
            threshold_sum += *map;
            map++;
        }
    }
    threshold_avg = (threshold_sum / 80) / 148;
    //printf("平均阈值 = %d\n", threshold_avg);
}
void threshold_decrease(void)
{
    uint8_t threshold_avg = 36;
    uint8_t* map = fullBuffer;
    for (uint8_t i = 0; i < 120; i++)
    {
        for (uint8_t j = 0; j < 188; j++)
        {
            if (*map > threshold_avg)
            {
                *map = 0;
            }
            else if (*map <= threshold_avg)
            {
                *map = threshold_avg - *map;
                if (*map > 15)
                {
                    *map = 15;
                }
            }
            map++;
        }
    }
    map = fullBuffer;
    for (uint8_t i = 0; i < 120; i++)
    {
        for (uint8_t j = 0; j < 188; j++)
        {
            printf("%d,", *map);
            map++;
        }
        printf("\n");
    }
}
void threshold_add_gray(void)
{
    uint8_t* map = fullBuffer;
    uint8_t* gray_map = &gray_scale[0][0];
    for (uint8_t i = 0; i < 120; i++)
    {
        for (uint8_t j = 0; j < 188; j++)
        {
            *map = *map + *gray_map;
            map++;
            gray_map++;
        }
    }
}
////////////////////////////////////////////
//功能：二值化
//输入：灰度图片
//输出：二值化图片
//备注：
///////////////////////////////////////////
void THRE()
{
    uint8_t* map;
    uint8_t* my_map;
    uint8_t* gray_map = 0;
    uint8_t bound_thre = 0;
    map = fullBuffer;
    if (threshold_mode == 1 || threshold_mode == 0)
    {
        if (threshold_mode == 1 && step != 7)
        {
            threshold_1 = GetOTSU_part(fullBuffer, 10, 85, 20, 167) - threshold_minus1;
            threshold_2 = threshold_1 - threshold_minus2;
        }
        if (gray_dis != 0)
        {
            if (gray_dis == 1)
            {
                gray_map = &gray_scale[0][0];
            }
            else if (gray_dis == 2)
            {
                gray_map = &gray_scale2[0][0];
            }
            for (uint8_t i = 0; i < 120; i++)
            {
                my_map = &IMG[i][0];
                for (uint8_t j = 0; j < 188; j++)
                {
                    //提取边界
                    if (extract_bound == 1)
                    {
                        if (i > 0 && j > 0 && i < 120 && j < 187)
                        {
                            int grad_x = *(map + 1) - *(map - 1);
                            int grad_y = *(map + CAMERA_W) - *(map - CAMERA_W);
                            int cur = extract_k * abs(grad_x) + extract_k * abs(grad_y);
                            if (cur > 255)bound_thre = 255;

                            else  bound_thre = cur;
                            if (*map < bound_thre) { (*my_map) = 0; }
                            else
                            {
                                if (*map > threshold_1 - *gray_map + bound_thre)(*my_map) = 1;
                                else (*my_map) = 0;
                            }
                        }
                        else
                        {
                            if ((*map) > threshold_1 - *gray_map)
                                (*my_map) = 1;
                            else (*my_map) = 0;
                        }
                    }
                    //不提取边界
                    else
                    {
                        if ((*map) > threshold_1 - *gray_map)
                            (*my_map) = 1;
                        else (*my_map) = 0;
                    }
                    map++;
                    my_map++;
                    gray_map++;
                }
            }
        }
        else
        {
            for (int i = 0; i < 20; i++)
            {
                my_map = &IMG[i][0];
                for (int j = 0; j < 188; j++)
                {
                    if ((*map) > threshold_2)
                        (*my_map) = 1;
                    else (*my_map) = 0;
                    map++;
                    my_map++;
                }
            }
            for (int i = 20; i < 70; i++)
            {
                my_map = &IMG[i][0];
                for (int j = 0; j < 30; j++)
                {
                    if ((*map) > threshold_2)
                        (*my_map) = 1;
                    else (*my_map) = 0;
                    map++;
                    my_map++;
                }
                for (int j = 30; j < 157; j++)
                {
                    if ((*map) > threshold_1)
                        (*my_map) = 1;
                    else (*my_map) = 0;
                    map++;
                    my_map++;
                }
                for (int j = 157; j < 188; j++)
                {
                    if ((*map) > threshold_2)
                        (*my_map) = 1;
                    else (*my_map) = 0;
                    map++;
                    my_map++;
                }
            }
            for (int i = 70; i < 120; i++)
            {
                my_map = &IMG[i][0];
                for (int j = 0; j < 188; j++)
                {
                    if ((*map) > threshold_2)
                        (*my_map) = 1;
                    else (*my_map) = 0;
                    map++;
                    my_map++;
                }
            }
        }
    }
    if (threshold_mode == 2)
    {
        threshold_1 = GetOTSU_part(fullBuffer, 1, up_divide, 1, mid_divide);//左上
        threshold_2 = GetOTSU_part(fullBuffer, 1, up_divide, mid_divide, 188);//右上
        threshold_3 = GetOTSU_part(fullBuffer, up_divide, NEAR_LINE, 0, mid_divide);//左下
        threshold_4 = GetOTSU_part(fullBuffer, up_divide, NEAR_LINE, mid_divide, 188);
        for (int i = 0; i < up_divide; i++)
        {
            my_map = &IMG[i][0];
            for (int j = 0; j < mid_divide; j++)
            {
                if ((*map) > threshold_1)
                    (*my_map) = 1;
                else (*my_map) = 0;
                map++;
                my_map++;
            }
            for (int j = mid_divide; j < 188; j++)
            {
                if ((*map) > threshold_2)
                    (*my_map) = 1;
                else (*my_map) = 0;
                map++;
                my_map++;
            }
        }
        for (int i = up_divide; i < 120; i++)
        {
            my_map = &IMG[i][0];
            for (int j = 0; j < mid_divide; j++)
            {
                if ((*map) > threshold_3)
                    (*my_map) = 1;
                else (*my_map) = 0;
                map++;
                my_map++;
            }
            for (int j = mid_divide; j < 188; j++)
            {
                if ((*map) > threshold_4)
                    (*my_map) = 1;
                else (*my_map) = 0;
                map++;
                my_map++;
            }
        }
    }

}

/////////////
//功能：去阴影
/////////////
void Reduce_Noise(uint8_t* input, uint8_t(*input1)[CAMERA_W])
{
    uint8_t* img = input + CAMERA_W;//第一行的二级指针
    uint8_t(*imgline)[188] = input1 + 1;//第一行的一级指针

    for (int nr = 1; nr < NEAR_LINE - 1; nr++)
    {
        img++;//获得第nr行第一个的二级指针
        for (int nc = 1; nc < CAMERA_W - 1; nc++)
        {
            if (*img == black
                && (*(*(imgline - 1) + nc) + *(*(imgline + 1) + nc) + *(img + 1) + *(img - 1) > 2))
            {
                *img = white;
            }
            else if (*img == white
                && (*(*(imgline - 1) + nc) + *(*(imgline + 1) + nc) + *(img + 1) + *(img - 1) < 2))
            {
                *img = black;
            }
            img++;
            if (nc == CAMERA_W - 2)img++;//nc仅寻到camear_w-1，所以要在最后结束前再加一次，凑够一行
        }
        imgline++;//得到第nr行的一级指针
    }
}

