////////////////////////////////////////////
//功能：寻找白条子连通性的同时自适应阈值
//输入：
//输出：
//备注：
///////////////////////////////////////////
void find_all_connect_easy()///
{

    uint8_t i_start = NEAR_LINE;
    uint8_t i = i_start - 1;
    top_road = 0;
    road_range* pRoad = &myroad_continue[i];//选道的白条子属性
    road* currLine = &my_road[i_start];//当前行的赛道
    road* preLine = currLine--;//上一行的赛道, currLine现在指向的是my_road[NEAR_LINE-1],preLine指向的是my_road[NEAR_LINE]
    uint8_t pre_j_select = j_continue[i_start];//用来标记上一行选道的白条子编号
    int16_t x;//列数
    for (i = NEAR_LINE - 1; i >= FAR_LINE; i--, pRoad--, currLine--, preLine--)
    {
        uint8_t pre_connect_id = 0;//用来记录第i行白条子与第i+1行相连的处在第i+1行的白条子编号
        uint8_t j = preLine->connected[1].left, white_num_i = 0;//j从上一行最左边的白条子左边开始寻找;  white_num_i用来记录第i行的白条子的数目
        // uint8_t width_max = 0;//用来记录第i行最宽的白条子的宽度
        uint8_t j_select = MISS;//标记选择作为选道的白条子的编号
        //uint8_t new_width = 0;//用来记录相连的长度，*没用
        uint8_t error = 0;
        uint8_t d_min = 187;//计算差值的变量
        //printf("j[%d]=%d\n",i,j);
        road_range new_white = search_white_range_begin(i, j);//找到第i行的第一个白条子
        j = new_white.right;
        //printf("right[%d]=%d\n", i, j);
        while (j != MISS && white_num_i < white_num_MAX - 1)      //找到白条且符合条件
        {
            uint8_t connect_id = is_connect(&new_white, preLine, pre_j_select);//new_white表示的是第i行的某个白条子属性，preLine是第i+1行的赛道属性，pre_j_select为i+1行选道的白条子编号
            /* if (i == 50)
             {
                 printf("connect_id[%d]=%d\n", i, connect_id);
                 printf("j=%d\n", j);
             }*/
            if (connect_id)     //找到了相连的白条子
            {
                white_num_i++;
                currLine->connected[white_num_i] = new_white;//给my_road[120]赋值
            }
            else if (pre_connect_id == preLine->white_num)//本次不相连，且上一次已经和最后一个白条相连，本行搜索结束
                break;
            if (connect_id == pre_j_select) //找到了与上一行选道的白条子相连的白条子
            {
                uint8_t left = new_white.left;
                uint8_t right = new_white.right;
                uint8_t wide = right - left;
                uint8_t mid = (left + right) / 2;
                //选择与last_midline差值小的作为选道
                error = My_abs(mid - last_midline);
                // printf("left=%d\n", new_white.left);
                // printf("right=%d\n", new_white.right);
                if (error <= d_min && wide >= 15 && white_num_i <= 3)//优先选择宽度符合条件的白条子
                {
                    // printf("left999=%d\n", new_white.left);
                    d_min = error;
                    mid_choose = mid;
                    j_select = white_num_i;
                    //printf("mid_choose[%d]%d", i_start - 1, mid_choose);
                }
                else if ((white_num_i >= 4) && error <= d_min && (wide >= 2 || white_num_i == 1))//当前行白条数较多时，可能是斑马线放开宽度条件
                {
                    d_min = error;
                    mid_choose = mid;
                    j_select = white_num_i;
                }
                if (j_select == MISS && wide >= 5)//实在没找到，放开宽度选择
                {
                    if (error <= d_min)
                    {
                        //d_min = error;
                        mid_choose = mid;
                        j_select = white_num_i;

                    }
                }


            }
            //搜索下一个白条
           // if (j > preLine->connected[pre_num].right) break;//该行寻找的白条子的右边界已经超过上一行最右的白条子的右边界，停止搜寻
            new_white = search_white_range((uint8_t)i, (uint8_t)j + 1);
            j = new_white.right;
            pre_connect_id = connect_id;
        }
        //一行完毕，结算
        currLine->white_num = white_num_i;
        if (white_num_i > white_num_max)
            white_num_max = white_num_i;//给white_num_max赋值
        j_continue[i] = pre_j_select = j_select;
        if (j_select != MISS)
            *pRoad = currLine->connected[j_select];//给myroad_continue[120]赋值
        if (i <= NEAR_LINE - (block / 2) && i >= FAR_LINE + (block / 2) && j_select != MISS)//对于选道的白条子再次二值化
        {
            x = pRoad->left;
            if (x >= (block / 2) && x <= RIGHT_SIDE - (block / 2)) adaptive_threshold_2((uint8_t)i, (uint8_t)x);
            x = pRoad->right;
            //printf("x=[%d]%d\n", i, currLine->connected[j_select].left);
            if (x >= (block / 2) && x <= RIGHT_SIDE - (block / 2)) adaptive_threshold_2((uint8_t)i, (uint8_t)x);
            x = pRoad->left;
            uint8_t connect_flag = 0;
            uint8_t width_new = 0;
            road_range select_white;
            do
            {
                new_white = search_white_range_begin((uint8_t)i, (uint8_t)x);
                connect_flag = is_connect_continue(&new_white, (pRoad + 1));
                x = new_white.right + 1;
                //找白条子最宽的为赛道
                if (connect_flag && new_white.width >= width_new)
                {
                    width_new = new_white.width;
                    select_white = new_white;
                }
            } while (x - 1 <= currLine->connected[white_num_i].right);
            if (connect_flag)
            {
                //printf("left[%d]=%d\n",i, new_white.left);
                *pRoad = select_white;
            }
        }
        // printf("j_continue[%d]=%d", i, j_continue[i]);
        if (!white_num_i)//如果当前的白条数为0
        {
            top_road = i + 1;
            break;
        }
    }
}
road_range search_white_range_begin(uint8_t line, uint8_t col)//用来找到line行，从col列开始往右的白条子，找到就返回这个白条子的属性road_range
{
    int16_t j;
    uint8_t* map = &IMG[line][col];
    uint8_t* Initial = &IMG[0][0];
    road_range result = { MISS, MISS, MISS };
    for (j = col; j <= RIGHT_SIDE; j++, map++)
    {
        if (j == LEFT_SIDE && (*map))//白条位于左边界
        {
            result.left = LEFT_SIDE;
            //printf("left0=%d\n", result.left);
            //开始向后一个一个像素点找这个白条右边界
            map++;
            j++;
            while ((*map) && j <= RIGHT_SIDE)
            {
                map++;
                j++;
            }
            result.right = j - 1;
            //printf("right0=%d\n", result.right);
            result.width = result.right - result.left + 1;
            return result;//找到就返回这个白条子的属性road_range
        }
        else if ((*map) && j == col)//如果开始处为白，先找到白条的左边界
        {
            //开始向前一个一个像素点找这个白条左边界
            map--;
            j--;
            while ((*map) && j >= LEFT_SIDE)
            {
                if (map != Initial) map--;
                j--;
            }
            result.left = j + 1;//找到了白条的左边界
            //printf("left1=%d\n", result.left);
            map = &IMG[line][col];
            j = col;
            //开始向后一个一个像素点找这个白条右边界
            map++;
            j++;
            while ((*map) && j <= RIGHT_SIDE)
            {
                map++;
                j++;
            }
            result.right = j - 1;
            result.width = result.right - result.left + 1;
            //printf("right1=%d\n", result.right);
            return result;//找到就返回这个白条子的属性road_range

        }
        else if ((*map))//如果开始处为黑，直接找白条的右边界
        {
            result.left = (uint8_t)j;
            if (line == 57)
            {
                // printf("left2=%d\n", result.left);
                // printf("col=%d\n", col);
            }

            //开始向前一个一个像素点找这个白条右边界
            map++;
            j++;
            while ((*map) && j <= RIGHT_SIDE)
            {
                map++;
                j++;
            }
            result.right = j - 1;
            // printf("right2=%d\n", result.right);
            result.width = result.right - result.left + 1;
            return result;//找到就返回这个白条子的属性road_range
        }

    }
    return result;//没找到就返回result = { MISS, MISS, MISS };
}

////////////////////////////////////////////
//功能：查找联通性
//输入：当前行的白条子属性road_range* new_white，上一行的赛道属性road* pre_line，上一行的选道的白条子编号uint8_t continue_id
//输出：编号
//备注：
///////////////////////////////////////////
uint8_t is_connect(road_range* new_white, road* pre_line, uint8_t continue_id)
{
    uint8_t j_d;
    uint8_t jd_return = 0;
    uint8_t u_left = new_white->left;//当前行
    uint8_t u_right = new_white->right;
    for (j_d = 1; j_d <= pre_line->white_num; j_d++)//寻找上一行与当前行的白条子是否联通
    {
        road_range* pre_road = &pre_line->connected[j_d];
        if (u_left <= pre_road->right && u_right >= pre_road->left)//如果相连0
        {
            if (!jd_return)
                jd_return = j_d;//j_d到本次函数跑完  等于上一行的白条子数目或者是上一行选道的白条子编号
            if (j_d == continue_id)
                return continue_id;//只有相连并且与上一行的选道的白条子相连通才是希望的白条子
        }
    }
    return jd_return;//没找到返回0   或返回一个相连的但不与选道联通的白条子编号
}

////////////////////////////////////////////
//功能：用来找到line行，从col列开始往右的白条子，找到就返回这个白条子的属性road_range
//输入：行数 line, 列数 col
//输出：road_range
//备注：指针提速
///////////////////////////////////////////
road_range  search_white_range(uint8_t line, uint8_t col)//用来找到line行，从col列开始往右的白条子，找到就返回这个白条子的属性road_range
{
    uint8_t j;
    uint8_t* map = &IMG[line][col];
    road_range result = { MISS, MISS, MISS };
    for (j = col; j <= RIGHT_SIDE; j++, map++)
    {
        if ((*map))//遇白条左边界
        {
            result.left = j;
            //开始向后一个一个像素点找这个白条右边界
            map++;
            j++;
            while ((*map) && j <= RIGHT_SIDE)
            {
                map++;
                j++;
            }
            result.right = j - 1;
            result.width = result.right - result.left + 1;
            return result;//找到就返回这个白条子的属性road_range
        }
    }
    return result;//没找到就返回result = { MISS, MISS, MISS };
}
void adaptive_threshold_2(uint8_t y, uint8_t x)
{
    int half_block = block / 2;
    int thres = 0;
    uint8_t* map = fullBuffer;
    uint8_t* my_map = NULL;
    uint8_t num = 0;
    //uint8_t min_thres = 0;

    //计算平均阈值
    for (int i = -half_block + y; i <= half_block + y; i++) {
        map = fullBuffer + i * CAMERA_W;
        for (int j = -half_block + x; j <= half_block + x; j++) {
            thres += *(map + j);
        }
    }
    thres = thres / (block * block) - 4;
    //printf("thres[%d][%d]=%d\n", y , x, thres);
     //开始二值化
    for (int i = -half_block + y; i <= half_block + y; i++)
    {
        map = fullBuffer + i * CAMERA_W;
        my_map = &IMG[i][0];
        for (int j = -half_block + x; j <= half_block + x; j++) {

            num++;
            if (*(map + j) > thres)
            {
                *(my_map + j) = 1;

            }
            else *(my_map + j) = 0;
        }
    }
}

uint8_t is_connect_continue(road_range* new_white, road_range* pre_line)
{

    uint8_t u_left = new_white->left;//当前行
    uint8_t u_right = new_white->right;
    road_range* pre_road = pre_line;
    if (u_left <= pre_road->right && u_right >= pre_road->left)//如果相连0
    {
        return 1;//只有相连并且与上一行的选道的白条子相连通才是希望的白条子
    }

    return 0;//没找到返回0
}
////////////////////////////////////////////
//功能：查找父节点
//输入：节点编号//
//输出：最老祖先
//备注：含路径压缩
///////////////////////////////////////////
int find_f(int node)
{
    if (f[node] == node)return node;//找到最古老祖先，return
    f[node] = find_f(f[node]);//向上寻找自己的父节点
    return f[node];
}

////////////////////////////////////////////
//功能：提取跳变沿 并对全部白条子标号
//输入：IMG[120][188]
//输出：white_range[120]
//备注：指针提速
///////////////////////////////////////////
void search_white_range1()
{
    uint8_t i = 0;
    uint8_t j = 0;
    uint8_t istart = NEAR_LINE;//处理起始行
    uint8_t iend = FAR_LINE;//处理终止行
    uint8_t tnum = 0;//当前行白条数
    all_connect_num = 0;//白条编号初始化
    uint8_t* map = NULL;
    for (i = istart; i >= iend; i--)
    {
        map = &IMG[i][LEFT_SIDE];//指针行走加快访问速度
        tnum = 0;
        for (j = LEFT_SIDE; j <= RIGHT_SIDE; j++, map++)
        {
            if ((*map))//遇白条左边界
            {
                tnum++;
                if (tnum >= white_num_MAX)break;
                range* now_white = &white_range[i].area[tnum];
                now_white->left = j;

                //开始向后一个一个像素点找这个白条右边界
                map++;
                j++;

                while ((*map) && j <= RIGHT_SIDE)
                {
                    map++;
                    j++;
                }
                now_white->right = j - 1;
                now_white->connect_num = ++all_connect_num;//白条数加一，给这个白条编号
            }
        }
        white_range[i].num = tnum;
    }
}

////////////////////////////////////////////
//功能：寻找白条子连通性，将全部联通白条子的节点编号刷成最古老祖先的节点编号
//输入：
//输出：
//备注：
///////////////////////////////////////////
void find_all_connect()
{
    //f数组初始化
    for (int i = 1; i <= all_connect_num; i++)
        f[i] = i;

    //u为up d为down 即为当前处理的这两行中的上面那行和下面那行
    //u_num：上面行白条数
    //u_left：上面行当前白条左边界
    //u_right：上面行当前白条右边界
    //i_u：当前处理的这个白条是当前这行（上面行）白条中的第i_u个
    int u_num, i_u, u_left, u_right;
    int d_num, i_d, d_left, d_right;
    all_range* u_white = NULL;
    all_range* d_white = NULL;
    for (int i = NEAR_LINE; i > FAR_LINE; i--)//因为每两行每两行比较 所以循环到FAR_LINE+1
    {
        u_num = white_range[i - 1].num;
        d_num = white_range[i].num;
        u_white = &white_range[i - 1];
        d_white = &white_range[i];
        i_u = 1; i_d = 1;

        //循环到当前行或上面行白条子数耗尽为止
        while (i_u <= u_num && i_d <= d_num)
        {
            //变量先保存，避免下面访问写的冗杂且访问效率低
            u_left = u_white->area[i_u].left;
            u_right = u_white->area[i_u].right;
            d_left = d_white->area[i_d].left;
            d_right = d_white->area[i_d].right;

            if (u_left <= d_right && u_right >= d_left)//如果两个白条联通
                f[find_f(u_white->area[i_u].connect_num)] = find_f(d_white->area[i_d].connect_num);//父节点连起来

            //当前算法规则，手推一下你就知道为啥这样了
            if (d_right > u_right)i_u++;
            if (d_right < u_right)i_d++;
            if (d_right == u_right) { i_u++; i_d++; }
        }
    }
}

////////////////////////////////////////////
//功能：寻找赛道
//输入：
//输出：
//备注：
///////////////////////////////////////////
void find_road()
{
    my_memset(j_continue, MISS, CAMERA_H);
    road* tmy_road = &my_road[NEAR_LINE];
    uint8_t j = LEFT_SIDE, white_num_istart = 0;//j用来寻找一行的白条子便利的变量; white_num_istart是用来表示istart行的白条子数目
    uint8_t width_max = 0;//用来找最宽的白条子
    uint8_t j_select = 0;//用来标记选择作为赛道的白条子编号
    road_range root = search_white_range(NEAR_LINE, j);//得到istart行的第一个白条子
    j = root.right;
    while (j != MISS && white_num_istart < white_num_MAX)
    {
        //确定上一个白条无误，统计信息
        if (j - root.left > 5)//确保最下面一行的白条子有效
        {
            white_num_istart++;//符合条件，白条子数目加1
            tmy_road->connected[white_num_istart] = root;//给my_road[istart]赋值
            if (root.width > width_max)//确定istart行最宽的白条子
            {
                width_max = root.width;
                j_select = white_num_istart;//找到最宽的白条子编号
            }
        }
        //搜索下一个白条
        root = search_white_range(NEAR_LINE, j + 1);
        j = root.right;
    }
    tmy_road->white_num = white_num_istart;
    myroad_continue[NEAR_LINE] = tmy_road->connected[j_select];//选最宽的白条作为选道
    j_continue[NEAR_LINE] = j_select;
}
////////////////////////////////////////////
//功能：寻找赛道
//输入：
//输出：
//备注：
///////////////////////////////////////////
void find_road1()
{
    uint8_t istart = NEAR_LINE;
    uint8_t iend = FAR_LINE;
    //top_road = NEAR_LINE;//赛道最高处所在行数，先初始化话为最低处
    int road_f = -1;//赛道所在连通域父节点编号，先初始化为-1，以判断是否找到赛道
    int while_range_num = 0, roud_while_range_num = 0;
    all_range* twhite_range = NULL;
    road* tmy_road = NULL;
    //寻找赛道所在连通域
    // 寻找最中心的白条子
    for (int i = 1; i <= white_range[istart].num; i++)
        if (white_range[istart].area[i].left <= CAMERA_W / 2
            && white_range[istart].area[i].right >= CAMERA_W / 2 && (white_range[istart].area[i].right - white_range[istart].area[i].left) >= 90)
            road_f = find_f(white_range[istart].area[i].connect_num);

    if (road_f == -1)//若赛道没在中间，在NEAR_LINE行选一行最长的认为这就是赛道
    {
        int widthmax = 0, jselect = 1;
        for (int i = 1; i <= white_range[istart].num; i++)
            if (white_range[istart].area[i].right - white_range[istart].area[i].left > widthmax)
            {
                widthmax = white_range[istart].area[i].right - white_range[istart].area[i].left;
                jselect = i;
            }
        road_f = find_f(white_range[istart].area[jselect].connect_num);//找到父节点编号
    }
    //现在我们已经得到了赛道所在连通域父节点编号，接下来把所有父节点编号是road_f的所有白条子扔进赛道数组就行了
    for (int i = istart; i >= iend; i--)
    {
        //变量保存，避免之后写的冗杂且低效
        twhite_range = &white_range[i];
        tmy_road = &my_road[i];
        while_range_num = twhite_range->num;//每行白条数量
        tmy_road->white_num = 0;
        roud_while_range_num = 0;
        for (int j = 1; j <= while_range_num; j++)
        {
            if (find_f(twhite_range->area[j].connect_num) == road_f)
            {
                tmy_road->white_num++; roud_while_range_num++;
                tmy_road->connected[roud_while_range_num].left = twhite_range->area[j].left;
                tmy_road->connected[roud_while_range_num].right = twhite_range->area[j].right;
                tmy_road->connected[roud_while_range_num].width = twhite_range->area[j].right - twhite_range->area[j].left;
            }
        }
    }
}
void find_road_state()
{
    if (step == traverse && (traverse_state == 2 || traverse_state == 3))
    {
        traverse_bridge_road_choose();
    }
    else if (step == single_side)
    {
        single_side_road_choose();
    }
    else
    {
        find_road1();
    }
}

////////////////////////////////////////////
//功能：返回相连下一行白条子编号
//输入：i_start起始行  j_start白条标号
//输出：白条标号
//备注：认为下一行与本行赛道重叠部分对多的白条为选定赛道
///////////////////////////////////////////
uint8_t find_continue(uint8_t i_start, uint8_t j_start)
{
    uint8_t j_return;
    uint8_t j;
    uint8_t width_max = 0;
    uint8_t width_new = 0;
    uint8_t left = 0;
    uint8_t right = 0;
    uint8_t dright, dleft, uright, uleft;
    j_return = MISS;//如果没找到，输出255
    if (j_start > my_road[i_start].white_num)
        return MISS;
    //选一个重叠最大的
    for (j = 1; j <= my_road[i_start - 1].white_num; j++)
    {
        dleft = my_road[i_start].connected[j_start].left;
        dright = my_road[i_start].connected[j_start].right;
        uleft = my_road[i_start - 1].connected[j].left;
        uright = my_road[i_start - 1].connected[j].right;
        if (//相连
            dleft <= uright
            &&
            dright >= uleft
            )
        {
            //计算重叠大小
            if (dleft < uleft) left = uleft;
            else left = dleft;

            if (dright > uright) right = uright;
            else right = dright;

            width_new = right - left + 1;

            if (width_new > width_max)
            {
                width_max = width_new;
                j_return = j;
            }
        }

    }
    return j_return;
}

////////////////////////////////////////////
//功能：通用决定双边
//输入：
//输出：
//备注：
///////////////////////////////////////////
void ordinary_two_line(void)
{
    uint8_t i;
    uint8_t j;
    uint8_t j_continue[CAMERA_H];//第一条连通路径
    uint8_t i_start;
    uint8_t i_end;
    uint8_t j_start = MISS;
    int width_max;

    //寻找起始行最宽的白条子
    i_start = NEAR_LINE;
    i_end = FAR_LINE - 1;
    width_max = 0;
    for (j = 1; j <= my_road[i_start].white_num; j++)
    {
        if (my_road[i_start].connected[j].width > width_max)
        {
            width_max = my_road[i_start].connected[j].width;
            j_start = j;
        }
    }
    j_continue[i_start] = j_start;
    if ((step == left_roundabout && roundabout_state == 3) || (step == right_roundabout && (roundabout_state == 8 || roundabout_state == 7 || roundabout_state == 2 || roundabout_state == 9)))
    {
        left_roundabout_road_choose(j_continue);
    }
    else if ((step == right_roundabout && roundabout_state == 3) || (step == left_roundabout && (roundabout_state == 8 || roundabout_state == 7 || roundabout_state == 9 || roundabout_state == 2)))
    {
        right_roundabout_road_choose(j_continue);
    }
    else if (step == traverse && traverse_state == 2)
    {
        traverse_bridge_get_twp_line(j_continue);
    }
    else if (step == single_side)
    {
        single_side_bridge_two_line(j_continue);
    }
    else
    {
        //记录连贯区域编号
        for (i = i_start; i > i_end; i--)
        {
            //如果相连编号大于该行白条数，非正常，从此之后都MISS
            if (j_continue[i] > my_road[i].white_num)
            {
                j_continue[i - 1] = MISS;
            }
            else
            {
                j_continue[i - 1] = find_continue(i, j_continue[i]);
            }

        }
    }


    //全部初始化为MISS
    my_memset(left_line, MISS, CAMERA_H);
    my_memset(right_line, MISS, CAMERA_H);


    for (i = i_start; i > i_end; i--)
    {
        if (j_continue[i] >= 1 && j_continue[i] <= my_road[i].white_num)
        {
            top_road = i;
            left_line[i] = my_road[i].connected[j_continue[i]].left;
            right_line[i] = my_road[i].connected[j_continue[i]].right;

        }
        else
        {
            left_line[i] = MISS;
            right_line[i] = MISS;
        }
    }
    if (step == 1)
    {
        renew_road();
    }
}

////////////////////////////////////////////
//功能：数组初始化
//输入：uint8_t* ptr 数组首地址, uint8_t num初始化的值, uint8_t size数组大小
//输出：
//备注：因为k66库中认为memset函数不安全，所以无法使用；因此需要自己写一个my_memset
///////////////////////////////////////////
void my_memset(uint8_t* ptr, uint8_t num, uint8_t size)
{
    uint8_t* p = ptr;
    uint8_t my_num = num;
    uint8_t Size = size;
    for (int i = 0; i < Size; i++, p++)
    {
        *p = my_num;
    }
}


////////////////////////////////////////////
//功能：中线合成
//输入：左右边界
//输出：中线
//备注：
///////////////////////////////////////////
void get_mid_line(void)
{
    my_memset(mid_line, MISS, CAMERA_H);

    for (int i = NEAR_LINE; i >= FAR_LINE; i--)
    {
        if (left_line[i] != MISS)//直道
        {
            mid_line[i] = (left_line[i] + right_line[i]) / 2;
        }

        else
        {
            mid_line[i] = MISS;
        }
    }

}
uint8_t mid(uint8_t i)
{
    if (mid_line[i] >= 187 || mid_line[i] <= 1)
    {
        if (i > 25)
        {
            return mid(i - 1);
        }
        if (i <= 25)
        {
            return 0;
        }
    }
    else
    {
        return 1;
    }
}

void define_mid_255()
{
    if (mid(NEAR_LINE) == 0)
    {
        for (int i = NEAR_LINE; i > top_road + 5; i--)
        {
            mid_line[i] = 94;
        }
    }
}
