void element_check()//人机交互
{
    if (pre_step == 5 || pre_step == 6 || pre_step == 8 || pre_step == 7)
    {
        if (step == 0)
        {
            element_sort = element_sort / 10;
        }
    }
    if (roundabout_num >= element_round_d && cross_num >= element_cross_d && element_sort != 0)
    {
        element_ok = 1;
    }
    if (element_sort == 0)
    {
        element_ok = 0;
    }
}

